    INTENTS.push({ tag: "site_rotate", patterns: ["rotate your device","landscape mode","tap to rotate","screen rotation message","phone rotate karo","best experience rotate","why does it say rotate my phone"],
        responses: ["📱 **'TAP TO ROTATE' — nothing's broken!**\nSome screens (especially games) show a rotate prompt: **'For the best experience, please rotate your device to landscape'** 🔄\n\n- **Landscape** = phone sideways (wide like a TV) — that's how the arcade games are designed\n- Just turn your phone (or tap the 🔄 button if auto-rotate is off in your phone settings)\n- Chat, profile & study pages work fine in portrait too\n\nWider screen = more game. Rotate and race! 🏎️"] });
    INTENTS.push({ tag: "site_rank", patterns: ["your rank not ranked","what is my rank","rank kaise badhaye","how do ranks work here","not ranked meaning","get ranked","rank widget","my rank shows not ranked"],
        responses: ["📈 **'YOUR RANK: Not ranked' → time to fix that!**\nThe rank card tracks where you stand against other players.\n\n**How to get ranked & climb:**\n1. 🎮 Play the leaderboard games — Flappy, Dino, Snake, Pac-Man — your BEST scores feed the rankings\n2. 🧠 Crush the Weekly Quiz — it's ranked by fastest total time, top 3 even win medals\n3. 🔁 Keep improving — scores sync when you're online\n\nCheck the 🏆 **Leaderboard** page (tabs per game) to see the TOP PLAYERS and exactly what you're chasing. From 'Not ranked' to #1 is just one great run away ⚡"] });
    INTENTS.push({ tag: "site_invite", patterns: ["friend invite join decline","someone invited me","invite popup","accept friend request","join or decline invite","friend request kaise accept kare","invite notification","multiplayer invite"],
        responses: ["🤝 **Invites — JOIN or DECLINE:**\nWhen a friend invites you (to be friends or into a multiplayer room), a popup slides in:\n- ✅ **JOIN** — accept instantly (you're in the room / friends list)\n- ✗ **DECLINE** — politely skip; nothing breaks, you can be invited again\n\nFriend invites also live in the 👥 **Friends** page (search a player → GO → add). And the 🔔 bell shows **Global** announcements vs **Private** messages.\n\nMultiplayer tip: invites are how Tic Tac Toe Online, Car Game 3D and ArcadeCraft battles start — JOIN fast, opponents hate waiting 😄"] });
